// Generated by bottle-rulebook/stainless/sync-studio.mjs. Edit the source in bottle-rulebook, then sync.
// Sketch to stainless design: read a drawn or photographed outline, judge it as single and double
// wall at a target capacity, find the closest designs that can be made, and the closest products
// on the market. Shared by tests and the Slot Studio bottles page (copied by sync-studio.mjs).
//
// Outlines are compared in proportion only: both scaled to the same height, the gap is the
// root-mean-square difference in radius at 64 heights, as a fraction of height. Size comes from
// the target capacity.
import * as S from './model.mjs';

export const K = 64;
export const FRACS = Array.from({ length: K }, (_, k) => k / (K - 1));
export const CANVAS = { w: 400, h: 500, axis: 200 }; // drawing coordinates; y runs down
const BUFFER = 0.001; // a fitted design clears every limit by this fraction of the rule's scale
const SLACK = 0.001; // the margin polish may give up this much gap
const SAME_SHAPE = 0.008;
const SAME_SIZE = 0.15;

export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gauss(r) {
  let u = 0;
  while (u === 0) u = r();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r());
}
const clamp01 = (v) => Math.min(1, Math.max(0, v));

// ---------- reading an outline ----------
function fillGaps(a) {
  if (!a.some((v) => !isNaN(v))) return null;
  const out = a.slice();
  for (let k = 0; k < a.length; k++) {
    if (!isNaN(a[k])) continue;
    let i = k - 1; while (i >= 0 && isNaN(a[i])) i--;
    let j = k + 1; while (j < a.length && isNaN(a[j])) j++;
    out[k] = i < 0 ? a[j] : j >= a.length ? a[i] : a[i] + ((a[j] - a[i]) * (k - i)) / (j - i);
  }
  return out;
}

// strokes: arrays of {x, y} in drawing coordinates. The base is the lowest point drawn and the
// mouth the highest. At each of the K heights the drawing is cut by a horizontal line and the
// outermost crossing kept; with both sides drawn the radius is half the distance between them.
export function silhouette(strokes, axisX = CANVAS.axis) {
  let top = Infinity, bot = -Infinity, nl = 0, nr = 0;
  const tol = 3;
  for (const s of strokes) for (const q of s) {
    top = Math.min(top, q.y); bot = Math.max(bot, q.y);
    if (q.x < axisX - tol) nl++; else if (q.x > axisX + tol) nr++;
  }
  const H = bot - top;
  if (!(H >= 40)) return null;
  const twoSided = Math.min(nl, nr) >= 0.2 * (nl + nr);
  const L = new Array(K).fill(NaN), R = new Array(K).fill(NaN);
  const add = (k, x) => {
    if (twoSided) {
      if (x <= axisX + tol) L[k] = isNaN(L[k]) ? x : Math.min(L[k], x);
      if (x >= axisX - tol) R[k] = isNaN(R[k]) ? x : Math.max(R[k], x);
    } else {
      const d = Math.abs(x - axisX);
      R[k] = isNaN(R[k]) ? d : Math.max(R[k], d);
    }
  };
  for (let k = 0; k < K; k++) {
    const yk = bot - FRACS[k] * H;
    for (const s of strokes) {
      if (s.length === 1 && Math.abs(s[0].y - yk) < 0.5) add(k, s[0].x);
      for (let i = 1; i < s.length; i++) {
        const a = s[i - 1], b = s[i];
        if ((a.y - yk) * (b.y - yk) > 0) continue;
        if (a.y === b.y) { add(k, a.x); add(k, b.x); } else add(k, a.x + ((yk - a.y) / (b.y - a.y)) * (b.x - a.x));
      }
    }
  }
  const right = fillGaps(R);
  if (!right) return null;
  let half = right, center = axisX;
  if (twoSided) {
    const left = fillGaps(L);
    if (!left) return null;
    half = right.map((v, k) => (v - left[k]) / 2);
    center = right.reduce((acc, v, k) => acc + (v + left[k]) / 2, 0) / K;
  }
  if (half.every((v) => v < 2)) return null;
  return { r: half.map((v) => Math.max(v, 0) / H), twoSided, top, bot, center };
}

// An uploaded sketch or photo, as RGBA pixels: the outline is the outermost marks on each row,
// against the paper's colour. Returns two strokes (right and left side) in drawing coordinates,
// so the result shows on the canvas and can be redrawn by hand. Null if nothing bottle-like.
export function traceImage(px, W, H) {
  const lum = (i) => 0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2];
  const border = [];
  for (let x = 0; x < W; x += 2) { border.push(lum(4 * x), lum(4 * ((H - 1) * W + x))); }
  for (let y = 0; y < H; y += 2) { border.push(lum(4 * y * W), lum(4 * (y * W + W - 1))); }
  border.sort((a, b) => a - b);
  const bg = border[border.length >> 1];
  const thr = Math.max(28, bg * 0.22);
  const left = new Array(H).fill(-1), right = new Array(H).fill(-1);
  for (let y = 0; y < H; y++) {
    let l = -1, r = -1, count = 0;
    for (let x = 0; x < W; x++) {
      if (bg - lum(4 * (y * W + x)) > thr) { if (l < 0) l = x; r = x; count++; }
    }
    if (count >= 2 && r - l > 2) { left[y] = l; right[y] = r; }
  }
  const rows = [];
  for (let y = 0; y < H; y++) if (left[y] >= 0) rows.push(y);
  if (rows.length < H * 0.15) return null;
  const top = rows[0], bot = rows[rows.length - 1];
  const lower = rows.filter((y) => y > top + 0.55 * (bot - top));
  const mids = lower.map((y) => (left[y] + right[y]) / 2).sort((a, b) => a - b);
  const c = mids[mids.length >> 1];
  const span = bot - top;
  const s = Math.min((CANVAS.h - 60) / span, (CANVAS.w - 40) / W);
  const base = CANVAS.h - 30;
  // Half-widths per row, smoothed over a few rows so pixel steps don't read as ridges.
  const raw = new Array(H).fill(NaN);
  for (let y = top; y <= bot; y++) if (left[y] >= 0) raw[y] = Math.min(c - left[y], right[y] - c);
  const halfAt = (y) => {
    let s = 0, n = 0;
    for (let d = -3; d <= 3; d++) { const v = raw[y + d]; if (v >= 0) { s += v; n++; } }
    return n ? s / n : NaN;
  };
  const rightSide = [], leftSide = [];
  for (let y = bot; y >= top; y -= 2) {
    if (left[y] < 0) continue;
    const half = halfAt(y);
    if (!(half >= 0)) continue;
    const Y = base - (bot - y) * s;
    rightSide.push({ x: CANVAS.axis + half * s, y: Y });
    leftSide.push({ x: CANVAS.axis - half * s, y: Y });
  }
  if (rightSide.length < 10) return null;
  // Close the base and the mouth, as a hand drawing would.
  rightSide.unshift({ x: CANVAS.axis, y: base });
  rightSide.push({ x: CANVAS.axis, y: rightSide[rightSide.length - 1].y });
  return [rightSide, leftSide];
}

export function signature(prof) {
  const H = prof.z[prof.z.length - 1];
  return FRACS.map((f) => S.interp(f * H, prof.z, prof.r) / H);
}

export function gap(a, b) {
  let s = 0;
  for (let k = 0; k < K; k++) s += (a[k] - b[k]) ** 2;
  return Math.sqrt(s / K);
}

// ---------- judging the sketch as drawn ----------
export const procOf = (book) => Object.fromEntries(Object.entries(book.process_params).map(([k, v]) => [k, v.value]));

// Scale a sketch so its label capacity is the target, for one wall system. Returns the profile and measurements.
export function scaleToCapacity(sig, form, cfg, targetMl, proc) {
  const base = S.sketchProfile(sig, FRACS, 100, form);
  let lo = 0.2, hi = 12;
  let best = null;
  for (let it = 0; it < 40; it++) {
    const s = Math.sqrt(lo * hi);
    const prof = S.scaleProfile(base, s);
    const m = S.measure(prof, cfg, proc);
    best = { prof, m, scale: s };
    if (Math.abs(m.capacity_ml - targetMl) < 0.5) break;
    if (m.capacity_ml < targetMl) lo = s; else hi = s;
  }
  return best;
}

// The sketch as drawn, single wall and double wall, at the target capacity with typical gauges.
export function judgeSketch(sig, { capacity, book, state }) {
  const proc = procOf(book);
  const form = S.formOf(S.sketchProfile(sig, FRACS, 100, 'bottle'));
  const out = { form };
  for (const wall of ['single', 'double']) {
    const cfg = Object.assign({ form, wall, route: 'tube' }, S.TYPICAL[wall]);
    const { prof, m } = scaleToCapacity(sig, form, cfg, capacity, proc);
    const ev = S.evaluate(m, S.ctxOf(cfg), book, state);
    out[wall] = { cfg, prof, m, ev };
  }
  return out;
}

// ---------- the closest designs that can be made ----------
const SHAPE_PARAMS = {
  bottle: ['body_d_mm', 'body_h_mm', 'taper', 'waist', 'waist_pos', 'belly', 'belly_pos', 'shoulder_h_mm', 'shoulder_p', 'neck_len_mm', 'heel_r_mm'],
  tumbler: ['body_d_mm', 'body_h_mm', 'draft_deg', 'waist', 'waist_pos', 'belly', 'belly_pos', 'heel_r_mm'],
};
const GAUGES = { single: ['t_mm'], double: ['t_inner_mm', 't_outer_mm', 'gap_mm'] };
const BY_NAME = Object.fromEntries(S.PARAMS.map((q) => [q.name, q]));

// Measures p; returns it with its outline if it passes every active make and standard rule by the
// buffer (integer measures against integer limits need none) and meets the capacity target.
export function check(p, ctx) {
  const prof = S.buildProfile(p);
  const m = S.measure(prof, p, ctx.proc);
  if (ctx.cap && Math.abs(m.capacity_ml - ctx.cap) > ctx.cap * ctx.capTol) return null;
  const ev = S.evaluate(m, S.ctxOf(p), ctx.book, ctx.state);
  if (!ev.feasible) return null;
  for (const x of ev.rules) {
    if (x.rule.tier !== 'make' && x.rule.tier !== 'standard') continue;
    const lims = Array.isArray(x.rule.limit) ? x.rule.limit : [x.rule.limit];
    const exact = Number.isInteger(x.value) && lims.every(Number.isInteger);
    if (!exact && x.raw < BUFFER * x.rule.scale) return null;
  }
  return { m, ev, minNorm: ev.minNorm, sig: signature(prof) };
}

function toParams(x, base, names) {
  const p = Object.assign({}, base);
  names.forEach((n, j) => { const q = BY_NAME[n]; p[n] = Number((q.lo + clamp01(x[j]) * (q.hi - q.lo)).toFixed(4)); });
  return p;
}

// (1+1) evolution strategy from one seed with form, wall, route and mouth fixed: a move is kept only
// if it still passes and its outline gets no further from the sketch; then a short polish raises
// the smallest margin while the gap stays within SLACK of the best fit.
function refine(seed, sk, ctx, r) {
  const names = SHAPE_PARAMS[seed.p.form].concat(GAUGES[seed.p.wall]);
  let x = names.map((n) => { const q = BY_NAME[n]; return clamp01((seed.p[n] - q.lo) / (q.hi - q.lo)); });
  const start = check(seed.p, ctx);
  let best = start ? Object.assign({ p: seed.p, g: gap(start.sig, sk) }, start) : null;
  let g = best ? best.g : gap(seed.sig, sk);
  const step = (sigma) => {
    const y = x.slice();
    let moved = false;
    for (let j = 0; j < y.length; j++) if (r() < 0.35) { y[j] = clamp01(y[j] + sigma * gauss(r)); moved = true; }
    if (!moved) { const j = Math.floor(r() * y.length); y[j] = clamp01(y[j] + sigma * gauss(r)); }
    return y;
  };
  let sigma = 0.08;
  for (let it = 0; it < ctx.iters; it++) {
    const y = step(sigma);
    const q = toParams(y, seed.p, names);
    const c = check(q, ctx);
    const gq = c ? gap(c.sig, sk) : Infinity;
    if (gq <= g) { x = y; g = gq; best = Object.assign({ p: q, g: gq }, c); sigma = Math.min(0.3, sigma * 1.25); }
    else sigma = Math.max(0.003, sigma * 0.95);
  }
  if (!best) return null;
  const limit = best.g + SLACK;
  sigma = 0.03;
  for (let it = 0; it < ctx.polish; it++) {
    const y = step(sigma);
    const q = toParams(y, seed.p, names);
    const c = check(q, ctx);
    const gq = c ? gap(c.sig, sk) : Infinity;
    if (gq <= limit && c.minNorm > best.minNorm) { x = y; best = Object.assign({ p: q, g: gq }, c); sigma = Math.min(0.1, sigma * 1.25); }
    else sigma = Math.max(0.003, sigma * 0.95);
  }
  best.fitted = names.some((n) => best.p[n] !== seed.p[n]);
  return best;
}

const groupOf = (d) => d.p.form + '|' + d.p.wall + '|' + d.family;

function pickSeeds(sk, pool, perGroup) {
  const scored = pool.map((d) => ({ d, g: gap(d.sig, sk) })).sort((a, b) => a.g - b.g);
  const groups = {}, out = [];
  for (const s of scored) {
    const list = groups[groupOf(s.d)] || (groups[groupOf(s.d)] = []);
    if (list.length >= perGroup || list.some((o) => gap(o.sig, s.d.sig) < SAME_SHAPE)) continue;
    list.push(s.d);
    out.push(s.d);
  }
  return out;
}

const TIERS = [[SAME_SHAPE, SAME_SIZE], [SAME_SHAPE / 2, SAME_SIZE / 2], [0, 0]];
function rank(cands, k) {
  cands.sort((a, b) => a.g - b.g);
  const out = [];
  for (const [shape, size] of TIERS) {
    for (const c of cands) {
      if (out.length >= k) break;
      if (out.includes(c)) continue;
      const repeat = out.some((o) => groupOf(o) === groupOf(c) && gap(o.sig, c.sig) <= shape &&
        Math.abs(o.m.capacity_ml - c.m.capacity_ml) <= size * o.m.capacity_ml);
      if (!repeat) out.push(c);
    }
  }
  return out.sort((a, b) => a.g - b.g);
}

// pool: dataset designs {id, p, m, family, sig} that pass the active rules. Seeds are the closest
// few per form, wall and mouth family within the capacity target; each is refined, and the
// closest distinct results come back as {p, m, ev, sig, g, minNorm, fitted, parent, family}.
export function findDesigns(sk, o) {
  const ctx = { proc: procOf(o.book), book: o.book, state: o.state, cap: o.cap || 0, capTol: o.capTol ?? 0.1,
    iters: o.iters || 220, polish: o.polish || 60 };
  const pool = ctx.cap ? o.pool.filter((d) => Math.abs(d.m.capacity_ml - ctx.cap) <= ctx.cap * ctx.capTol) : o.pool;
  const seeds = pickSeeds(sk, pool, o.perGroup || 3);
  const r = rng(o.seed || 1);
  const cands = [];
  for (const s of seeds) {
    const b = refine(s, sk, ctx, r);
    if (b) cands.push(Object.assign(b, { parent: s.id, family: b.m.mouth_family }));
  }
  return { picks: rank(cands, o.k || 5), seeds: seeds.length, pool: pool.length };
}

// ---------- the market ----------
// Market products as design-like records: an outline from the photo (or from the listed
// dimensions), scaled to the listed capacity with typical gauges for its wall.
export function marketRecords(market, book) {
  const proc = procOf(book);
  const out = [];
  for (const p of market.products) {
    let sig = p.sig, form = p.form;
    // Listed height, diameter and mouth: build the bottle at those sizes and keep them. It is not
    // rescaled to the label, because the plain model holds more than the real bottle and rescaling
    // would move the listed mouth off its lid family. Capacity is the label's.
    if (!sig && p.height_mm) {
      const q = Object.assign({ form: p.form, wall: p.wall, route: 'tube', taper: 0, draft_deg: p.draft_deg || 0, waist: 0, waist_pos: 0.5, belly: 0, belly_pos: 0.5,
        shoulder_p: 1.2, heel_r_mm: 6, shoulder_h_mm: p.form === 'bottle' ? 28 : 0, neck_len_mm: p.form === 'bottle' ? 16 : 0 }, S.TYPICAL[p.wall],
        { body_d_mm: p.diameter_mm, mouth_id_mm: p.mouth_mm || 0 });
      for (const k of Object.keys(S.TYPICAL.single).concat(Object.keys(S.TYPICAL.double))) if (q[k] === undefined) q[k] = 0;
      const lidH = p.form === 'tumbler' ? proc.lid_h_tumbler_mm : (p.mouth_mm || 0) < 52 ? proc.lid_h_narrow_mm : proc.lid_h_wide_mm;
      q.body_h_mm = p.height_mm - lidH - q.shoulder_h_mm - q.neck_len_mm;
      const prof = S.buildProfile(q);
      const m = S.measure(prof, q, proc);
      m.model_capacity_ml = m.capacity_ml;
      m.capacity_ml = p.capacity_ml;
      out.push(Object.assign({}, p, { sig: signature(prof), form: p.form, cfg: q, prof, m, source: 'dimensions' }));
      continue;
    }
    if (!sig) { out.push(Object.assign({}, p, { sig: null })); continue; }
    // An outline read from a photo has no units: it is scaled to the label capacity, so its sizes are approximate.
    form = form || S.formOf(S.sketchProfile(sig, FRACS, 100, 'bottle'));
    const cfg = Object.assign({ form, wall: p.wall, route: 'tube' }, S.TYPICAL[p.wall]);
    const { prof, m } = scaleToCapacity(sig, form, cfg, p.capacity_ml, proc);
    out.push(Object.assign({}, p, { sig, form, cfg, prof, m, source: p.image ? 'photo' : 'dimensions' }));
  }
  return out;
}

// The products whose outline is closest to the sketch, preferring the same form, and preferring
// outlines read from a photo over those drawn from a few listed dimensions.
export function marketMatches(sk, records, k = 6, form) {
  return records.filter((p) => p.sig)
    .map((p) => ({ p, g: gap(p.sig, sk) + (form && p.form !== form ? 0.02 : 0) + (p.image ? 0 : 0.004) }))
    .sort((a, b) => a.g - b.g).slice(0, k);
}

// An example outline (right side, millimetres) as one stroke in drawing coordinates.
export const EXAMPLES = {
  classic: { label: 'Classic', pts: [[0, 0], [34, 0], [36.5, 4], [37, 12], [37, 160], [34, 176], [26, 188], [22, 196], [22, 214], [0, 214]] },
  waisted: { label: 'Grip waist', pts: [[0, 0], [33, 0], [36, 5], [36.5, 40], [32, 85], [36, 130], [36.5, 155], [31, 172], [25, 182], [24, 200], [0, 200]] },
  carafe: { label: 'Carafe', pts: [[0, 0], [40, 0], [44, 6], [46, 40], [44, 90], [36, 130], [26, 160], [21, 178], [21, 200], [0, 200]] },
  tumbler: { label: 'Tumbler', pts: [[0, 0], [34, 0], [37, 4], [38, 20], [44, 160], [45, 175], [0, 175]] },
  bulb: { label: 'Bulb', pts: [[0, 0], [24, 0], [28, 10], [40, 60], [46, 110], [42, 150], [28, 175], [14, 190], [13, 205], [0, 205]] },
};
export function exampleStrokes(name) {
  const pts = EXAMPLES[name].pts;
  const H = pts[pts.length - 1][1];
  const s = (CANVAS.h - 60) / H, base = CANVAS.h - 30;
  return [pts.map(([rr, z]) => ({ x: CANVAS.axis + rr * s, y: base - z * s }))];
}
